    correction: [{"quoi":"نترجم المعطى","math":"عددان متقابلان مجموعهما منعدم<span dir=\"ltr\" class=\"expr\">: C = -(-1 + √2)</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-x + 1 - √2 = 1 - √2</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">-x = 1 - √2 - (1 - √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">1 - √2 - (1 - √2) = 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 0</span>"}],
