    correction: [{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = -a + b + 2 - π</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = -(-b + 2) + b + 2 - π</span>"},{"quoi":"نزيل القوس","math":"<span dir=\"ltr\" class=\"expr\">E = b + 2 - π + b - 2</span>"},{"quoi":"نجمع الحدود المتشابهة","math":"نجمع الأعداد الناطقة مع بعضها و الأعداد الصمّاء مع بعضها"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 2b - π</span>"}],
