    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">x - [√3 + (<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> - √3 - 3)] - 2 + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - √3 = x - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">x - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3 = -2 - √3</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">x = -2 - √3 - (-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-2 - √3 - (-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3) = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"}],
