    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">-√5 - [-√5 + (-y + √5 - √5)] - [-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> + √5] - [-1 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>] - <span class=\"frac\"><span class=\"num\">51</span><span class=\"den\">5</span></span> = y - 4 - √5</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">y - 4 - √5 = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + √5</span>"},{"quoi":"نعزل y","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + √5 - (-4 - √5)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + √5 - (-4 - √5) = <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">4</span></span> + 2√5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">4</span></span> + 2√5</span>"}],
