    enonce: "جد العدد الحقيقي a بحيث: <span dir=\"ltr\" class=\"expr\">a + [√2 - (a - √2 + √2)] + a + a - a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2</span>",
    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">a + [√2 - (a - √2 + √2)] + a + a - a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> = a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √2</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √2 = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2 - (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2 - (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √2) = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> - 2√2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> - 2√2</span>"}],
